# ABOUTME: Call cases for POSIX's declared subs, which the return-type oracle calls to hold POSIX.tpm to perl.
# ABOUTME: Each sub maps to a list of argument lists, one call per declared candidate; exempt subs (never called) are not listed.
# Setup perl itself runs before any call, so a case can hand the oracle a
# real fd, filehandle or dirhandle without relying on another sub's call
# ordering: each sub that touches one gets its own, since one sub's case
# running (e.g. close) must not invalidate another's (e.g. dup).
use POSIX ();
# return_oracle.pl only requires POSIX.pm; it never `use`s it, so most
# exported names (every one outside POSIX.pm's own forward-declared
# %replacement/%reimpl eval) have no stub CV yet and the driver's
# `exists &POSIX::name` callable() check fails for them. A bare import
# (POSIX's own Exporter::export autovivifies `\&{"POSIX::$sym"}` for
# every default-exported name as a side effect) primes every one of
# them, matching what held_to_perl.pl calls "priming a bare use" before
# it reads POSIX's export lists.
POSIX->import();
open my $seed, '>', 'posix-scratch.txt' or die "seed: $!";
print $seed "hello\n";
close $seed;
